import React from 'react';

const Nav = () => (
    <nav className="site-nav">
        <ul>
            <li><a href="#home">Home</a></li>
            <li><a href="#films">Films</a></li>
            <li><a href="#about">About</a></li>
            <li><a href="#contact">Contact</a></li>
        </ul>
    </nav>
);

export default Nav;
